1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type ClaimStep = {
19	  op: "claim";
20	  policy: number;
21	  incident: {
22	    cause: string;
23	    damages: Damage[];
24	  };
25	};
26	
27	export type Step = QuoteStep | ClaimStep;
28	
29	export type Customer = {
30	  yearsWithMHPCO: number;
31	};
32	
33	export type Scenario = {
34	  customer: Customer;
35	  steps: Step[];
36	};
37	
38	export type ScenarioResults = {
39	  results: unknown[];
40	};
