42	const sum = (amounts: number[]): number =>
43	  amounts.reduce((total, amount) => total + amount, 0);
44	
45	const PROCESSING_FEE = 5;
46	
47	// Binary floating point makes exact multiples land a hair off (100 * 1.1 + 5 =
48	// 115.00000000000001); snap to cent precision so only genuine fractions round up.
49	const roundUpInMHPCOsFavour = (amount: number): number =>
50	  Math.ceil(Number(amount.toFixed(6)));
51	
52	// One entry per insurable type: every fact the office knows about a type lives
53	// here, so adding a type is a single edit.
54	type ItemKind = {
55	  basePremium: number;
56	  insuranceValue: number;
57	  isComponent: boolean;
58	};
59	
60	const ITEM_CATALOGUE: Record<string, ItemKind> = {
61	  sword: { basePremium: 100, insuranceValue: 1000, isComponent: false },
62	  amulet: { basePremium: 60, insuranceValue: 600, isComponent: false },
63	  staff: { basePremium: 80, insuranceValue: 800, isComponent: false },
64	  potion: { basePremium: 40, insuranceValue: 400, isComponent: false },
65	  rune: { basePremium: 25, insuranceValue: 250, isComponent: true },
66	  moonstone: { basePremium: 25, insuranceValue: 250, isComponent: true },
67	};
68	
69	const kindOf = (item: Item): ItemKind => ITEM_CATALOGUE[item.type];
70	
71	const basePremiumOf = (item: Item): number => kindOf(item).basePremium;
72	
73	const BLOCK_SIZE = 3;
74	const BLOCK_BASE_PREMIUM = 60;
75	
76	const groupByType = (items: Item[]): Item[][] => {
77	  const itemsByType = new Map<string, Item[]>();
78	
79	  for (const item of items) {
80	    const sameTypeItems = itemsByType.get(item.type);
81	    if (sameTypeItems) sameTypeItems.push(item);
82	    else itemsByType.set(item.type, [item]);
83	  }
84	
85	  return [...itemsByType.values()];
86	};
87	
88	const isComponent = (item: Item): boolean => kindOf(item).isComponent;
89	
90	// A block is a special price for exactly 3 alike components; any other count,
91	// and any main item, is charged per item.
92	const sameTypeBasePremiumOf = (sameTypeItems: Item[]): number =>
93	  sameTypeItems.length === BLOCK_SIZE && isComponent(sameTypeItems[0])
94	    ? BLOCK_BASE_PREMIUM
95	    : sum(sameTypeItems.map(basePremiumOf));
96	
97	const policyBasePremiumOf = (items: Item[]): number =>
98	  sum(groupByType(items).map(sameTypeBasePremiumOf));
99	
100	const HIGH_ENCHANTMENT_THRESHOLD = 5;
101	
102	const isCursed = (item: Item): boolean => item.cursed === true;
103	
104	const isHighlyEnchanted = (item: Item): boolean =>
105	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
106	
107	// Item surcharges stack: each one whose condition holds contributes its rate.
108	const ITEM_SURCHARGES: { appliesTo: (item: Item) => boolean; rate: number }[] = [
109	  { appliesTo: isCursed, rate: 0.5 },
110	  { appliesTo: isHighlyEnchanted, rate: 0.3 },
111	];
112	
113	const itemSurchargeRateOf = (item: Item): number =>
114	  sum(
115	    ITEM_SURCHARGES.filter(({ appliesTo }) => appliesTo(item)).map(
116	      ({ rate }) => rate,
117	    ),
118	  );
119	
120	// Item-specific surcharges are charged on that item's own base premium, not on
121	// the policy total.
122	const itemSurchargesOf = (item: Item): number =>
123	  basePremiumOf(item) * itemSurchargeRateOf(item);
124	
125	// Everything outside the item list that a policy-wide modifier may depend on:
126	// who is asking, and where this quote sits in their history with the office.
127	type QuoteContext = {
128	  customer: Customer;
129	  precedingQuotes: number;
130	};
131	
132	const LOYALTY_YEARS_THRESHOLD = 2;
133	
134	const isLoyal = ({ customer }: QuoteContext): boolean =>
135	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
136	
137	const isFollowUpContract = ({ precedingQuotes }: QuoteContext): boolean =>
138	  precedingQuotes > 0;
139	
140	const alwaysApplies = (): boolean => true;
141	
142	// Policy modifiers stack the same way item surcharges do: each one whose
143	// condition holds contributes its signed rate. Discounts are negative so the
144	// whole table sums without sign-juggling at the call site.
145	const POLICY_MODIFIERS: {
146	  appliesTo: (context: QuoteContext) => boolean;
147	  rate: number;
148	}[] = [
149	  { appliesTo: alwaysApplies, rate: 0.1 }, // first insurance surcharge
150	  { appliesTo: isLoyal, rate: -0.2 },
151	  { appliesTo: isFollowUpContract, rate: -0.15 },
152	];
153	
154	// Policy-wide modifiers are charged on the base premium alone, never on base +
155	// item surcharges: a cursed sword quotes at 100 + 50 + 10 + 5 = 165, where the
156	// 10 is 10 % of 100 rather than of 150.
157	const policyModifierRateOf = (context: QuoteContext): number =>
158	  sum(
159	    POLICY_MODIFIERS.filter(({ appliesTo }) => appliesTo(context)).map(
160	      ({ rate }) => rate,
161	    ),
162	  );
163	
164	const quote = (step: QuoteStep, context: QuoteContext): number => {
165	  const policyBasePremium = policyBasePremiumOf(step.items);
166	  const itemSurcharges = sum(step.items.map(itemSurchargesOf));
167	  const policyModifiers = policyBasePremium * policyModifierRateOf(context);
168	
169	  return roundUpInMHPCOsFavour(
170	    policyBasePremium + itemSurcharges + policyModifiers + PROCESSING_FEE,
171	  );
172	};
173	
174	const DEDUCTIBLE_PER_DAMAGE = 100;
175	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
176	
177	const roundDownInMHPCOsFavour = (amount: number): number =>
178	  Math.floor(Number(amount.toFixed(6)));
179	
180	const insuranceSumOf = (items: Item[]): number =>
181	  sum(items.map((item) => kindOf(item).insuranceValue));
182	
183	const payoutForDamage = (damage: Damage): number =>
184	  damage.amount - DEDUCTIBLE_PER_DAMAGE;
185	
186	const claim = (step: ClaimStep, policy: QuoteStep) => {
187	  const cap = insuranceSumOf(policy.items) * CAP_MULTIPLE_OF_INSURANCE_SUM;
188	  const payout = roundDownInMHPCOsFavour(
189	    sum(step.incident.damages.map(payoutForDamage)),
190	  );
191	
192	  return { payout, remainingCap: cap - payout };
193	};
194	
195	export const runScenario = (scenario: Scenario): ScenarioResults => {
196	  return {
197	    results: scenario.steps.map((step, precedingQuotes) => {
198	      if (step.op === "claim") {
199	        return claim(step, scenario.steps[step.policy] as QuoteStep);
200	      }
201	
202	      return {
203	        premium: quote(step, { customer: scenario.customer, precedingQuotes }),
204	      };
205	    }),
206	  };
207	};
