export const runScenario = (scenario: Scenario): ScenarioResults => {
  return {
    results: scenario.steps.map((step, precedingSteps) => {
      if (step.op === "claim") {
        return claim(step, policyOf(scenario, step));
      }

      return {
        // Steps, not quotes: with only quote-then-claim scenarios under test the
        // two counts agree. A claim before a quote would make them diverge, and
        // that is the deferred test's job to pin down.
